import React from 'react';
import { Box, Paper, Typography } from '@mui/material';
import AnimatedPage from '../../../layouts/AnimatedPage';
import SearchField from '../../../components/ModelPopup/SearchField';
import ReactTable from '../../../components/Table/ReactTable';
import useVoidReport from './useVoidReport';
import { Table } from '@tanstack/react-table';
import PosTablePagination from '../../../components/Table/PosTablePagination';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { appColors, brandColors, HEADER_GRADIENT } from '../../../theme/appColors';
import ReceiptLongIcon from '@mui/icons-material/ReceiptLong';

const VoidReport = () => {
  const { table, isLoading, setSearchText, totalCount } = useVoidReport();
  const { setPage } = usePageQuery();

  const handleSearch = (searchText: string) => {
    setSearchText(searchText);
  };

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    const newSize = parseInt(event.target.value, 10);
    table.setPageSize(newSize);
  };

  return (
    <AnimatedPage>
      <Box data-testid="voidReport" sx={{ backgroundColor: brandColors.contentBg, minHeight: '100%' }}>
        {/* Page Header */}
        <Paper
          elevation={0}
          sx={{ borderRadius: 2, mb: 2, overflow: 'hidden', boxShadow: '0 2px 12px rgba(15,29,77,0.12)' }}
        >
          <Box
            sx={{
              background: HEADER_GRADIENT,
              px: 3,
              py: 2,
              display: 'flex',
              alignItems: 'center',
              gap: 1.5,
            }}
          >
            <Box
              sx={{
                width: 38,
                height: 38,
                borderRadius: 1.5,
                backgroundColor: 'rgba(255,255,255,0.15)',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
              }}
            >
              <ReceiptLongIcon sx={{ color: '#fff', fontSize: 22 }} />
            </Box>
            <Box>
              <Typography sx={{ color: '#fff', fontWeight: 700, letterSpacing: 0.3 }} variant="h6">
                Void Report
              </Typography>
              <Typography sx={{ color: 'rgba(255,255,255,0.72)', fontSize: '0.78rem' }} variant="caption">
                Overview of voided transactions
              </Typography>
            </Box>
          </Box>
        </Paper>

        {/* Table Card */}
        <Paper
          elevation={0}
          sx={{ borderRadius: 2, overflow: 'hidden', boxShadow: '0 1px 6px rgba(0,0,0,0.07)' }}
        >
          {/* Search Toolbar */}
          <Box
            sx={{
              px: 2,
              py: 1.5,
              display: 'flex',
              justifyContent: 'flex-end',
              borderBottom: `1px solid ${appColors.blueGreyishLight[50]}`,
              backgroundColor: '#fff',
            }}
          >
            <SearchField
              buttonName={'Search'}
              placeholderName={'Name Or Code'}
              setSearchText={handleSearch}
            />
          </Box>

          {/* Table */}
          <Box sx={{ pb: 1, overflow: 'auto', maxWidth: '100%', minHeight: '520px', backgroundColor: '#fff' }}>
            <ReactTable
              isLoading={isLoading}
              {...(table as Table<object>)}
            />
          </Box>

          {/* Pagination */}
          {table.getTotalSize() !== 0 && (
            <Box sx={{ borderTop: `1px solid ${appColors.greenSmoke[40]}`, backgroundColor: '#fff' }}>
              <PosTablePagination
                count={totalCount}
                data-testid="pos-pagination"
                onPageChange={handlePaginationChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                page={table.getState().pagination.pageIndex}
                rowsPerPage={table.getState().pagination.pageSize}
                rowsPerPageOptions={[5, 10, 20]}
              />
            </Box>
          )}
        </Paper>
      </Box>
    </AnimatedPage>
  );
};

export default VoidReport;
