import {
  PaginationState,
  Row,
  getCoreRowModel,
  useReactTable,
} from '@tanstack/react-table';
import { CSSProperties, useMemo, useEffect, useState } from 'react';
import {
  IVoidDetails,
  IVoidDetailsReport,
} from '../../../core/Interface/voidSummaryReport.interface';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { 
    useVoidReportQuery,
} from '../../posApi';
import useVoidReportColumns from './useVoidReportColumns';

const useVoidReport = () => {
  const { page, setPage } = usePageQuery();
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: voidReportData,
    isLoading,
    isFetching,
    error,
  } = useVoidReportQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText: '',
  });

  useEffect(() => {
    setPage(pagination.pageIndex);
  }, [pagination.pageIndex, setPage]);

  const VoidReportDetailsMemo = useMemo(() => {
    const voidDetails = voidReportData?.data || [];
    return voidDetails as IVoidDetailsReport;
  }, [voidReportData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return (
      voidReportData &&
      VoidReportDetailsMemo.data &&
      VoidReportDetailsMemo.data.filter((record: IVoidDetails) => {
        const name = record.productName.toLowerCase();
        const code = record.productCode.toLowerCase();
        return name?.includes(text) || code?.includes(text);
      })
    );
  }, [VoidReportDetailsMemo.data, voidReportData, searchText]);

  const totalRecords = VoidReportDetailsMemo?.totalRecords ?? 0;

  const columns = useVoidReportColumns(
    pagination.pageIndex,
    pagination.pageSize
  );

  const table = useReactTable({
    data: error ? [] : filteredData ?? [],
    meta: {
      getRowStyles: (row: Row<IVoidDetails>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: totalRecords,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: VoidReportDetailsMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useVoidReport;
